mapper.update:
UPDATE proj_project_gate_reference SET deleted=1,version=version+1,
    updater=#{query.updater},update_time=CURRENT_TIMESTAMP(3)
WHERE tenant_id=#{query.tenantId} AND gate_id=#{query.gateId} AND id=#{query.referenceId}
  AND version=#{query.expectedVersion} AND deleted=0
  AND EXISTS (SELECT 1 FROM proj_project_gate g WHERE g.tenant_id=#{query.tenantId}
      AND g.project_id=#{query.projectId} AND g.id=#{query.gateId})

UPDATE proj_project SET task_tree_version=task_tree_version+1,updater=#{query.updater},update_time=CURRENT_TIMESTAMP(3)
WHERE tenant_id=#{query.tenantId} AND id=#{query.projectId} AND task_tree_version=#{query.expectedVersion}
  AND lifecycle_status='ACTIVE' AND deleted=0
